mapper.select:
SELECT  FROM conversations WHERE tenant_id=#{tenantId}
AND customer_id=#{customerId}AND id < #{cursor}
AND status=#{status}AND LOCATE(#{search},title)>0
ORDER BY id DESC LIMIT #{limit}

SELECT r.id AS runId,r.state AS runState,j.state AS jobState,j.error_code,r.generation_epoch,j.attempts,j.execution_version
FROM ai_runs r JOIN jobs j ON j.tenant_id=r.tenant_id AND j.id=r.job_id
WHERE r.tenant_id=#{tenantId} AND r.conversation_id=#{conversationId} AND r.generation_epoch=#{epoch}
